<script setup>
import { ref, watch } from 'vue';
import { Building2, ShieldCheck, Plus, Save, X } from 'lucide-vue-next';
import { http } from '../lib/http';
import { serverError, roleNames } from '../lib/ace';
const props=defineProps({tenantId:String,tenantName:String,role:String,companies:Array});
const emit=defineEmits(['created','change']);
const editName=ref(props.tenantName),newName=ref(''),newDialog=ref(false),err=ref(''),success=ref(''),saving=ref(false);
watch(()=>props.tenantName,v=>editName.value=v);
async function save(){saving.value=true;err.value='';success.value='';try{await http.put('/workspaces/current',{name:editName.value});success.value='Empresa atualizada.';emit('created')}catch(e){err.value=serverError(e)}finally{saving.value=false}}
async function create(){saving.value=true;err.value='';try{const {data}=await http.post('/workspaces',{name:newName.value});newDialog.value=false;newName.value='';emit('created');emit('change',data.data.id)}catch(e){err.value=serverError(e)}finally{saving.value=false}}
</script>
<template><div class="ace-page"><div class="ace-page-head"><div><div class="ace-eyebrow"><span class="ace-eyebrow-dot"></span> ESTRUTURA B2B</div><h1>Empresas<span>.</span></h1><p>Workspaces isolados, cada um com sua própria carteira, sites e equipe.</p></div><button v-if="role==='owner'" class="ace-btn ace-btn-primary" @click="newDialog=true"><Plus :size="16"/> Nova empresa</button></div>
<div v-if="err" class="ace-error">{{err}}</div><div v-if="success" class="ace-success">{{success}}</div><div class="ace-company-grid"><div v-for="company in companies" :key="company.id" class="ace-panel ace-company-card" :class="{'ace-company-current':company.id===tenantId}"><div class="ace-company-card-icon"><Building2 :size="23"/></div><h2>{{company.name}}</h2><p>{{roleNames[company.role] || company.role}}</p><div class="ace-company-card-foot"><span class="ace-status active">{{company.id===tenantId?'Empresa ativa':'Disponível'}}</span><button v-if="company.id!==tenantId" class="ace-btn ace-btn-soft ace-btn-sm" @click="emit('change',company.id)">Acessar</button></div></div></div>
<section class="ace-panel ace-settings-panel"><div class="ace-panel-heading"><div><div class="ace-small-label">IDENTIDADE DA EMPRESA</div><h2>Configuração do workspace ativo</h2></div><ShieldCheck :size="20"/></div><p class="ace-form-help">Os clientes, sites, senhas e usuários são vinculados ao workspace ativo. A API valida esse vínculo em todas as requisições.</p><div class="ace-settings-row"><v-text-field v-model="editName" label="Nome da empresa" :readonly="role!=='owner'"/><button v-if="role==='owner'" class="ace-btn ace-btn-primary" :disabled="saving" @click="save"><Save :size="16"/> Salvar</button></div></section>
<v-dialog v-model="newDialog" max-width="530"><div class="ace-dialog"><div class="ace-dialog-head"><div><div class="ace-eyebrow">NOVO WORKSPACE</div><h2>Criar empresa</h2><p>Uma nova base lógica isolada dentro do ACE.</p></div><button class="ace-icon-button" @click="newDialog=false"><X :size="20"/></button></div><div class="ace-dialog-body"><v-text-field v-model="newName" label="Nome da empresa"/></div><div class="ace-dialog-actions"><span class="ace-flex-spacer"></span><button class="ace-btn ace-btn-outline" @click="newDialog=false">Cancelar</button><button class="ace-btn ace-btn-primary" :disabled="saving" @click="create"><Plus :size="16"/> Criar</button></div></div></v-dialog>
</div></template>
